(function(){const cv=$('heroCanvas'),ctx=cv.getContext('2d');let W,H,pts=[];function rs(){W=cv.width=cv.offsetWidth;H=cv.height=cv.offsetHeight}rs();window.addEventListener('resize',rs);
for(let i=0;i<70;i++)pts.push({x:Math.random(),y:Math.random(),vx:(Math.random()-.5)*.0012,vy:(Math.random()-.5)*.0012});
(function loop(){ctx.clearRect(0,0,W,H);pts.forEach(p=>{p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>1)p.vx*=-1;if(p.y<0||p.y>1)p.vy*=-1});
ctx.strokeStyle='rgba(230,255,74,.12)';for(let i=0;i<pts.length;i++)for(let j=i+1;j<pts.length;j++){const dx=(pts[i].x-pts[j].x)*W,dy=(pts[i].y-pts[j].y)*H;if(Math.hypot(dx,dy)<130){ctx.beginPath();ctx.moveTo(pts[i].x*W,pts[i].y*H);ctx.lineTo(pts[j].x*W,pts[j].y*H);ctx.stroke()}}
pts.forEach(p=>{ctx.fillStyle='#e6ff4a';ctx.globalAlpha=.7;ctx.fillRect(p.x*W,p.y*H,2,2);ctx.globalAlpha=1});requestAnimationFrame(loop)})();
const feed=$('terminalFeed');const lines=["> acquiring micro-catalog: lo-fi tapes [OK] > sync pitch: SEPSIS stems → A24 (sim) [SENT] > KYPO6 headline viral: 412K views/hr [▲] > royalty sweep: 20 releases → Holdings [$] > patent filed: VOID//OCULUS v3 [PENDING] > playlist add: +1,204 followers today [▲] > sample pack sold: UNHOLY ANATOMY [$39]"];
let li=0;setInterval(()=>{feed.innerHTML+=lines[li%lines.length]+'<br>';feed.scrollTop=9999;li++;if(feed.children.length>20)feed.innerHTML=feed.innerHTML.split('<br>').slice(-8).join('<br>')},1400);
let price=284.12;const hist=[280,281,279,282,283,281,284,283,284];setInterval(()=>{price+=(Math.random()-.45)*1.4;$('zmhPrice').textContent=price.toFixed(2);const chg=((price-280)/280*100);$('zmhChg').textContent=(chg>=0?'+':'')+chg.toFixed(2)+'%';$('zmhChg').className='text-sm font-mono '+(chg>=0?'text-emerald-400':'text-red-400');hist.push(price);if(hist.length>20)hist.shift();drawSpark()},1800);
function drawSpark(){const c=$('miniSpark'),x=c.getContext('2d');x.clearRect(0,0,140,50);const mn=Math.min(...hist),mx=Math.max(...hist);x.strokeStyle='#e6ff4a';x.lineWidth=2;x.beginPath();hist.forEach((v,i)=>{const px=i/(hist.length-1)*140,py=45-((v-mn)/(mx-mn||1))*38;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}drawSpark();})();
