const INDEX=[...FILMS.map(f=>({t:f.title,c:'FILM',fn:()=>openFilm(f.id)})),...DOMAINS.map(d=>({t:d.url+' — '+d.name,c:'DOMAIN',fn:()=>openDomain(d.id)})),{t:'Acoustic Bench',c:'INSTITUTE',fn:()=>openInstitute('bench')},{t:'Spectra Lab',c:'INSTITUTE',fn:()=>openInstitute('spectra')},{t:'VOID//OCULUS',c:'INSTITUTE',fn:()=>openInstitute('oculus')},{t:'Goa Trance / Psytrance (Spotify)',c:'AUDIENCE',fn:()=>{scrollToId('audiences');loadSpotifyEmbed()}},{t:'@WellMeaningNeurotypicals (Instagram)',c:'AUDIENCE',fn:()=>openInstagram()},...PRODUCTS.map(p=>({t:p.name,c:'PRODUCT $'+p.price,fn:()=>{scrollToId('products');addCart(p.id)}})),...MUSIC.map((m,i)=>({t:m.t,c:(m.type?m.type.toUpperCase():'EDITION')+(m.year?' • '+m.year:'')+' • '+(m.sp?'ON SPOTIFY':'ARCHIVE ONLY'),fn:()=>(m.tracks?playTrack(i):loadRelease(i))})),{t:'Form-909 Warp',c:'SOFTWARE',fn:()=>scrollToId('software')},{t:'Signal Rot Mastering Suite',c:'SOFTWARE',fn:()=>scrollToId('software')},{t:'NOETIC Cognitive Command Deck',c:'SOFTWARE',fn:()=>scrollToId('software')},...CODE_HOLDINGS.map(p=>({t:p.name,c:'GITHUB IP',fn:()=>openCodeHolding(p.id)}))];
function openPalette(){$('palette').classList.remove('hidden');$('palette').classList.add('flex');setTimeout(()=>$('paletteIn').focus(),50);renderPalette('')}
function closePalette(){$('palette').classList.add('hidden');$('palette').classList.remove('flex');$('paletteIn').value=''}
function renderPalette(q){const list=INDEX.filter(x=>x.t.toLowerCase().includes(q.toLowerCase())).slice(0,9);$('paletteList').innerHTML=list.length?list.map((x,i)=>'<div onclick="pickPalette('+INDEX.indexOf(x)+')" class="flex items-center justify-between p-3 rounded-xl hover:bg-lime/10 cursor-pointer"><span class="font-bold text-sm">'+x.t+'</span><span class="font-mono text-[10px] text-lime">'+x.c+'</span></div>').join(''):'<div class="p-6 text-center text-mute font-mono text-[12px]">No assets match. Everything is acquirable though.</div>'}
function pickPalette(i){closePalette();INDEX[i].fn()}
$('paletteIn').addEventListener('input',e=>renderPalette(e.target.value));
